export const ALL_PROGRAM_PAGES: ProgramPageData[] = [
  ...PROGRAM_PAGES_PART_1,
  ...PROGRAM_PAGES_PART_2,
];

export function getProgramPageById(id: string): ProgramPageData {
  // Map secondary pathway aliases to their comprehensive 1,500+ word monograph counterparts
  const normalizedId =
    id === "niw-us"
      ? "eb1a-us"
      : id === "gtv-uk"
      ? "amc-au"
      : id;

  return (
    ALL_PROGRAM_PAGES.find((p) => p.id === normalizedId) || ALL_PROGRAM_PAGES[0]
  );
}
